  `label` varchar(50) NOT NULL,
  `dari` int NOT NULL,
  `hingga` int NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


DROP TABLE IF EXISTS `sch_psb`;
CREATE TABLE `sch_psb` (
  `id` int NOT NULL AUTO_INCREMENT,
  `no_pendaftaran` varchar(20) DEFAULT NULL,
  `status` enum('0','1','2','-1') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '0: terdaftar, 1: terverifikasi, 2: sudah selesai -1: ditolak',
  `nama` varchar(100) NOT NULL,
  `nisn` varchar(15) NOT NULL,
  `induk_sekolah` varchar(25) NOT NULL,
  `gender` enum('laki-laki','perempuan') NOT NULL DEFAULT 'laki-laki',
  `tempat_lahir` varchar(15) NOT NULL,
  `tanggal_lahir` date NOT NULL,
  `agama` varchar(7) NOT NULL DEFAULT 'Islam',
  `alamat` varchar(200) NOT NULL,
  `telepon` varchar(15) NOT NULL,
  `kewarganegaraan` varchar(15) NOT NULL DEFAULT 'Indonesia',
  `anak` int NOT NULL DEFAULT '1',
  `saudara_kandung` int NOT NULL DEFAULT '0',
  `saudara_tiri` int NOT NULL DEFAULT '0',
  `saudara_angkat` int NOT NULL DEFAULT '0',
  `status_ortu` enum('lengkap','yatim','piatu','yatim-piatu') NOT NULL DEFAULT 'lengkap',
  `tinggal` varchar(20) NOT NULL,
  `tamat_sekolah` varchar(30) NOT NULL,
  `pindah_sekolah` varchar(30) NOT NULL,
  `masuk_kelas` int NOT NULL,
  `gol_darah` enum('A','B','AB','o') NOT NULL,
  `penyakit` varchar(200) NOT NULL,
  `kelainan_fisik` varchar(100) NOT NULL,
  `hobi_organisasi` varchar(20) NOT NULL,
  `hobi_olahraga` varchar(20) NOT NULL,
  `hobi_lain` varchar(40) NOT NULL,
  `ayah_nama` varchar(20) NOT NULL,
  `ayah_nik` varchar(30) NOT NULL,
  `ayah_tempat_lahir` varchar(15) NOT NULL,
  `ayah_tanggal_lahir` date NOT NULL,
  `ayah_agama` varchar(8) NOT NULL DEFAULT 'Islam',
  `ayah_kewarganegaraan` varchar(12) NOT NULL DEFAULT 'Indonesia',
  `ayah_hidup` enum('hidup','meninggal') NOT NULL DEFAULT 'hidup',
  `ayah_alamat` varchar(200) NOT NULL,
  `ayah_telepon` varchar(15) NOT NULL,
  `ayah_pendidikan` varchar(10) NOT NULL,
  `ayah_pekerjaan` varchar(15) NOT NULL,
  `ayah_penghasilan` varchar(50) NOT NULL,
  `ibu_nama` varchar(20) NOT NULL,
  `ibu_nik` varchar(30) NOT NULL,
  `ibu_tempat_lahir` varchar(15) NOT NULL,
  `ibu_tanggal_lahir` date NOT NULL,
  `ibu_agama` varchar(8) NOT NULL DEFAULT 'Islam',
  `ibu_kewarganegaraan` varchar(12) NOT NULL DEFAULT 'Indonesia',
  `ibu_hidup` enum('hidup','meninggal') NOT NULL DEFAULT 'hidup',
  `ibu_alamat` varchar(200) NOT NULL,
  `ibu_telepon` varchar(15) NOT NULL,
  `ibu_pendidikan` varchar(10) NOT NULL,
  `ibu_pekerjaan` varchar(15) NOT NULL,
  `ibu_penghasilan` varchar(50) NOT NULL,
  `wali_nama` varchar(20) NOT NULL,
  `wali_nik` varchar(30) NOT NULL,
  `wali_tempat_lahir` varchar(15) NOT NULL,
  `wali_tanggal_lahir` date NOT NULL,
  `wali_agama` varchar(8) NOT NULL DEFAULT 'Islam',
  `wali_kewarganegaraan` varchar(12) NOT NULL DEFAULT 'Indonesia',
  `wali_hidup` enum('hidup','meninggal') NOT NULL DEFAULT 'hidup',
  `wali_alamat` varchar(200) NOT NULL,
  `wali_telepon` varchar(15) NOT NULL,
  `wali_pendidikan` varchar(10) NOT NULL,
  `wali_pekerjaan` varchar(15) NOT NULL,
  `wali_penghasilan` varchar(50) NOT NULL,
  `wali_hubungan` varchar(15) NOT NULL,
  `akta_lahir` varchar(200) NOT NULL,
  `kk` varchar(200) NOT NULL,
  `raport_terakhir` varchar(200) NOT NULL,
  `surat_rekomendasi` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `surat_kematian` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `pembayaran` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `foto` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


DROP TABLE IF EXISTS `sch_santri`;
CREATE TABLE `sch_santri` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tingkat` tinyint NOT NULL DEFAULT '1',
  `kelas` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1A',
  `status` enum('0','1','-1') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0',
  `foto` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `sch_sav_kas`;
CREATE TABLE `sch_sav_kas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama` varchar(200) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `sch_sav_tabungan`;
CREATE TABLE `sch_sav_tabungan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_kas` int DEFAULT NULL,
  `id_santri` int DEFAULT NULL,
  `keterangan` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nominal` int NOT NULL,
  `jenis` enum('1','-1') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1',
  `tanggal` date DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `created_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_santri` (`id_santri`),
  KEY `id_kas` (`id_kas`),
  CONSTRAINT `sch_sav_tabungan_ibfk_3` FOREIGN KEY (`id_kas`) REFERENCES `sch_sav_kas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch_sav_tabungan_ibfk_4` FOREIGN KEY (`id_santri`) REFERENCES `sch__santri` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


